def solve(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find bounding box of 8s
    min_r = min_c = float('inf')
    max_r = max_c = float('-inf')
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if result[r][c] == 0:
                result[r][c] = 2

    return result
